#include "modules/notes_state.hpp"
#include "modules/notes_drawing.hpp"
#include "modules/notes_presentation.hpp"
#include <algorithm>
#include <iostream>
#include <stdexcept>
namespace {unsigned checks{};void check(bool value,const char*why){++checks;if(!value)throw std::runtime_error(why);}}
