    std::vector<N>writes;bool fail{};NotesState state({}, {[&](const N&n){if(fail)throw std::runtime_error("Synthetic full disk");writes.push_back(n);},[](std::string_view){} });
    state.setWorkspaceBounds({0,0,1000,800},endfield::core::Point{30,40});check(state.createDrawing(id,123)&&writes.size()==1,"Drawing creation makes one explicit save");const auto*n=state.note(id);check(n&&n->kind==ehud::data::NoteKind::drawing&&n->width==300&&n->height==240&&n->x==30&&n->y==40&&n->createdAt==123,"Source drawing default size/placement/date");check(!state.editing()&&state.selection()==id&&n->drawing&&NotesDrawing(*n->drawing).strokes().empty(),"Selected drawing creates no text editor");
    NotesPresentationInput input;input.palette=NotesPalette::source(true,{.98,.83,.12,1});input.drawingColor=NotesColor{.2,.8,.9,1};NotesCardPresentation presentation(id);presentation.updateContent(state,input);
